-- ========================================================


local path_body     = "Unity_Export_Grp/Geometry/body"
local path_cloth_03 = "Unity_Export_Grp/Geometry/cloth_03"

local wetStartTime = 2.7



-- ========================================================

---@param idolLive3D_SuperTimeLineState_ table
function SuperTimeline_13600850_100Wet:__init( idolLive3D_SuperTimeLineState_ )
    
    self.idolLive3D_SuperTimeLineState = idolLive3D_SuperTimeLineState_
    self.lastClipId = nil -- 最后一次登记的 clipId

    self.isFXPlayed = false
end




-- 需手动调用 Delete()
function SuperTimeline_13600850_100Wet:__delete()
end



-- 每次重播 superTimeline 的入场cb:
function SuperTimeline_13600850_100Wet:StartPlay() 
    self.isFXPlayed = false 
end 


-- ---@param clipJson_ table @ c# class SuperTimelineClip 内数据
-- ---@param timelineStateEnv_ table
function SuperTimeline_13600850_100Wet:SelfUpdate( clipJson_, timelineStateEnv_ ) 


    local clipId = tostring(clipJson_.clipId)
    local isFirstFrame = (clipId ~= self.lastClipId)
    self.lastClipId = clipId
    

    if self.isFXPlayed ~= true and timelineStateEnv_.play.playTime > wetStartTime  then 
        self.isFXPlayed = true 
        --printError("-湿身-")
        local idolLive3D_InteractiveManager = self.idolLive3D_SuperTimeLineState.idolLive3D_InteractiveManager
        local roleTF = idolLive3D_InteractiveManager.roleGO.transform

        local bodyTF  = roleTF:Find(path_body)
        local clothTF = roleTF:Find(path_cloth_03)
        local bodyMR  = KTool.GetComponent(bodyTF.gameObject,  typeof(SkinnedMeshRenderer))
        local clothMR = KTool.GetComponent(clothTF.gameObject, typeof(SkinnedMeshRenderer))
    
        local allResources = idolLive3D_InteractiveManager.allResources
        local mat_body = allResources.materials["body"]
        local mat_cloth_03 = allResources.materials["cloth_03"]

        if isNotNull(mat_body) and isNotNull(mat_cloth_03) then 
            bodyMR.material  = mat_body
            clothMR.material = mat_cloth_03
        else 
            printError(" 没拿到材质球 ")
        end

    end 


    --- None,Hold 模式就是唯一一遍尾后帧,
    if timelineStateEnv_.play.loopInteger > 0 then 

        Events.Broadcast(IdolLive3D_States.EventSetUICustomGray, Live3D_UIKey.switchPanel, false, true) -- 不再置灰 switchBtn
        Events.Broadcast(IdolLive3D_States.EventSetUIBtnCustomClickFunc, Live3D_UIKey.switchPanel, nil ) -- 释放 switchBtn 的 客制点击功能

        self.idolLive3D_SuperTimeLineState.isPlaying = false
        self.idolLive3D_SuperTimeLineState:EndPLay()
    end 
end







return SuperTimeline_13600850_100Wet
